import React from 'react';
import { ComponentMeta, ComponentStory } from '@storybook/react';
import { Image } from '../..';

const IMAGE_URL = 'https://www.robin-noorda.com/uploads/1/6/8/3/16830688/3347022_orig.jpg';
const BEES_LOGO_URL = 'https://media.gazetadopovo.com.br/2022/02/18112552/LOGO_BEES.png';

export default {
  title: 'Feedback/Image',
  component: Image,
  argTypes: {
    src: {
      description: 'Source content for the main image of the component',
      type: 'string',
    },
    aspectRatio: {
      description: 'A number prop for the image, ideally is going to be a fraction',
      control: { type: 'text' },
    },
    variant: {
      description: 'Defines how the image will behave',
      options: ['fill', 'fit', 'stretch'],
      control: { type: 'radio' },
      defaultValue: { summary: 'fill' },
    },
    position: {
      description: 'Recieves a string with two parameters, x and y axis',
      type: 'string',
    },
    isInteractive: {
      description: 'Boolean value indication if image has hover or disabled overlay',
      type: 'boolean',
      defaultValue: false,
      control: { type: 'boolean' },
    },
    disabled: {
      description: 'Used with `isInteractive`, will add an white overlay on image',
      type: 'boolean',
      defaultValue: false,
      control: { type: 'boolean' },
    },
    customErrorImage: {
      description: 'Image props for a custom image on error',
      control: { type: 'object' },
    },
    css: {
      description: 'Css props for the image container',
      control: { type: 'object' },
    },
  },
  parameters: {
    docs: {
      description: {
        component:
          'How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { Image } from "@hexa-ui/components"`<br><br>How to use: `Image`',
      },
    },
  },
} as ComponentMeta<typeof Image>;

const Template: ComponentStory<typeof Image> = (args) => (
  <div style={{ width: 250 }}>
    <Image {...args} />
  </div>
);

export const DefaultImage = Template.bind({});
DefaultImage.args = {
  src: IMAGE_URL,
  width: '250px',
};

export const FillImage = Template.bind({});
FillImage.args = {
  src: IMAGE_URL,
  width: '250px',
};

export const FitImage = Template.bind({});
FitImage.args = {
  containerCss: { background: 'aliceblue' },
  variant: 'fit',
  src: IMAGE_URL,
  width: '250px',
};

export const StretchImage = Template.bind({});
StretchImage.args = {
  variant: 'stretch',
  src: IMAGE_URL,
  width: '250px',
};

export const CustomAspectRatio = Template.bind({});
CustomAspectRatio.args = {
  aspectRatio: 3 / 4,
  src: IMAGE_URL,
  width: '250px',
};

export const PositionImage = Template.bind({});
PositionImage.args = {
  position: '0% 0%',
  src: IMAGE_URL,
  width: '250px',
};

export const InteractiveImage = Template.bind({});
InteractiveImage.args = {
  isInteractive: true,
  src: IMAGE_URL,
  width: '250px',
};

export const DisabledImage = Template.bind({});
DisabledImage.args = {
  isInteractive: true,
  disabled: true,
  src: IMAGE_URL,
  width: '250px',
};

export const ErrorImage = Template.bind({});
ErrorImage.args = {
  src: 'not_found_url',
  width: '250px',
};

export const CustomErrorIllustration = Template.bind({});
CustomErrorIllustration.args = {
  src: 'not_found_url',
  customErrorImage: {
    src: BEES_LOGO_URL,
    alt: 'Custom Image',
  },
  width: '250px',
};
